final class ProfileViewController: UIViewController {
    private let client = APIClient()

    func loadProfile(id: String) {
        client.fetchProfile(id: id) { [weak self] profile in
            self?.render(profile)
        }
    }
}

final class PhotoUploader {
    private let client = APIClient()

    func upload(_ photo: Photo) async throws {
        try await client.send(photo)
    }
}

final class OrderSummaryViewModel {
    func currencyCode() -> String {
        UserDefaults.standard.string(forKey: "currencyCode") ?? "USD"
    }
}

@Observable final class CheckoutViewModel {
    var isPremium = false

    func refreshEntitlement() {
        isPremium = PurchaseManager.shared.hasActiveSubscription
    }
}

@Observable final class AppCoordinator {
    var path: [Route] = []

    func handle(_ event: ProfileView.Event) {
        switch event {
        case .didTapFollowers(let id): path.append(.followers(id: id))
        case .didTapSettings: path.append(.settings)
        }
    }
}

final class FeedViewController: UIViewController {
    private let client = APIClient()
    private let cache = NSCache<NSString, UIImage>()
    private var posts: [Post] = []

    override func viewDidLoad() {
        super.viewDidLoad()
        client.fetchPosts { [weak self] posts in
            self?.posts = posts
            self?.tableView.reloadData()
        }
    }

    func tableView(_ tableView: UITableView, cellForRowAt indexPath: IndexPath) -> UITableViewCell {
        let cell = tableView.dequeueReusableCell(withIdentifier: "Cell") as! FeedCell
        let post = posts[indexPath.row]
        client.fetchImage(post.imageURL) { image in
            cell.imageView.image = image
        }
        return cell
    }
}

final class AppCoordinator {
    let analytics: AnalyticsClient

    init() {
        self.analytics = AnalyticsClient.shared
    }

    func start(path: [Route]) {
        analytics.log(.appLaunched)
    }
}

protocol ProfileRepository {
    func profile(id: String) async throws -> Profile
}

final class RemoteProfileRepository: ProfileRepository {
    private let client: APIClient
    init(client: APIClient) { self.client = client }
    func profile(id: String) async throws -> Profile {
        try await client.get("/profiles/\(id)")
    }
}

final class CachingProfileRepository: ProfileRepository {
    private let remote: ProfileRepository
    private var cache: [String: Profile] = [:]
    init(remote: ProfileRepository) { self.remote = remote }
    func profile(id: String) async throws -> Profile {
        if let cached = cache[id] { return cached }
        let fetched = try await remote.profile(id: id)
        cache[id] = fetched
        return fetched
    }
}
